package com.loonext.android.features.settings

import com.loonext.android.core.i18n.SETTINGS_INDEX
import java.io.File
import kotlinx.serialization.Serializable
import kotlinx.serialization.json.Json
import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * #719: the index and the search are the shared ones.
 *
 * `settings-search-fixture.json` was generated by reading
 * packages/shared/src/settings-search.ts: the entries from its text, the search
 * vectors by running its `searchSettings`. Regenerate it when that file changes.
 * Passing here means this phone finds the same settings, in the same order, as
 * the web does for the same words.
 */
class SettingsSearchParityTest {

    @Serializable
    private data class FixtureEntry(
        val id: String,
        val section: String,
        val anchor: String,
        val page: String? = null,
        val en: List<String>,
        val fr: List<String>,
    )

    @Serializable
    private data class Vector(
        val query: String,
        val locale: String,
        val visible: String,
        val ids: List<String>,
    )

    @Serializable
    private data class Sections(val all: List<String>, val member: List<String>)

    @Serializable
    private data class Fixture(
        val sections: Sections,
        val index: List<FixtureEntry>,
        val vectors: List<Vector>,
    )

    private val fixture: Fixture by lazy {
        val text = checkNotNull(javaClass.getResource("/settings-search-fixture.json")) {
            "settings-search-fixture.json is missing from the test resources"
        }.readText()
        Json { ignoreUnknownKeys = true }.decodeFromString(Fixture.serializer(), text)
    }

    @Test
    fun `the index equals the shared one, entry for entry`() {
        assertTrue("the fixture is empty", fixture.index.size > 50)
        assertEquals(fixture.index.size, SETTINGS_INDEX.size)
        fixture.index.zip(SETTINGS_INDEX).forEach { (shared, here) ->
            assertEquals(shared.id, here.id)
            assertEquals(shared.section, here.section)
            assertEquals(shared.page, here.page)
            assertEquals("${shared.id} en", shared.en, here.en)
            assertEquals("${shared.id} fr", shared.fr, here.fr)
        }
    }

    @Test
    fun `every search gives the shared answer`() {
        assertTrue("no vectors", fixture.vectors.size > 20)
        assertTrue(
            "every vector is empty, so this would pass for the wrong reason",
            fixture.vectors.any { it.ids.isNotEmpty() },
        )
        for (v in fixture.vectors) {
            val visible = (if (v.visible == "member") fixture.sections.member else fixture.sections.all).toSet()
            val got = searchSettings(v.query, v.locale) { it in visible }.map { it.entry.id }
            assertEquals("\"${v.query}\" (${v.locale}, ${v.visible})", v.ids, got)
        }
    }

    @Test
    fun `time zone is found in every place it is set`() {
        val ids = searchSettings("time zone", "en") { true }.map { it.entry.id }
        assertTrue(ids.containsAll(listOf("workspace:time-zone", "hours:business-hours", "hours:closed-dates")))
    }

    @Test
    fun `a member never finds an owner-only setting`() {
        val results = searchPhoneSettings("time zone", "en", "member")
        assertTrue(results.none { it.entry.section == "workspace" || it.entry.section == "hours" })
        // Their own settings are still found.
        assertTrue(searchPhoneSettings("password", "en", "member").isNotEmpty())
        // An owner finds the workspace one.
        assertTrue(searchPhoneSettings("time zone", "en", "owner").any { it.entry.id == "workspace:time-zone" })
    }

    @Test
    fun `a result carries its group and section, and Hours and Automatic texts stay apart`() {
        val away = searchPhoneSettings("away reply", "en", "owner").first { it.entry.anchor == "away-reply" }
        assertEquals(SettingsSection.Hours, away.section)
        assertEquals(SettingsGroup.Messages, away.group)
        val rating = searchPhoneSettings("rating", "en", "owner").first { it.entry.anchor == "auto-text-rating" }
        assertEquals(SettingsSection.AutomaticTexts, rating.section)
    }

    @Test
    fun `every setting on a visible section opens a section on this phone`() {
        for (role in listOf("owner", "admin", "member", "bookkeeper")) {
            val visible = visibleSettingsSections(role).toSet()
            for (entry in SETTINGS_INDEX) {
                val section = phoneSectionOf(entry) ?: continue
                if (section in visible) {
                    assertFalse("${entry.id} has no group", settingsGroupOf(section).id.isEmpty())
                }
            }
        }
    }

    /**
     * An entry pointing at nothing: every `anchor = "…"` a settings card carries
     * must be in the index, and no two cards may claim the same one.
     */
    @Test
    fun `every card anchor is in the index and used once`() {
        val root = listOf(
            "src/main/kotlin/com/loonext/android/features/settings",
            "app/src/main/kotlin/com/loonext/android/features/settings",
            "apps/android/app/src/main/kotlin/com/loonext/android/features/settings",
        ).map(::File).firstOrNull { it.exists() } ?: error("settings sources not found")
        val used = root.walkTopDown()
            .filter { it.isFile && it.extension == "kt" }
            .flatMap { file -> Regex("""anchor = "([a-z0-9-]+)"""").findAll(file.readText()).map { it.groupValues[1] } }
            .toList()
        assertTrue("the scan found no anchors", used.size > 30)
        val known = SETTINGS_INDEX.map { it.anchor }.toSet()
        assertEquals("anchors with no index entry", emptyList<String>(), used.filter { it !in known })
        assertEquals("anchors on two cards", emptyList<String>(), used.groupBy { it }.filter { it.value.size > 1 }.keys.toList())
    }
}
